import{_ as t,o as s,c as e,a0 as i}from"./chunks/framework.CLbANrvH.js";const k=JSON.parse('{"title":"Feature Flags","description":"","frontmatter":{"title":"Feature Flags"},"headers":[],"relativePath":"zh/concepts/feature-flags.md","filePath":"zh/concepts/feature-flags.md","lastUpdated":1791849617000}'),d={name:"zh/concepts/feature-flags.md"};function l(n,a,r,h,o,c){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="feature-flags" tabindex="-1">Feature Flags <a class="header-anchor" href="#feature-flags" aria-label="Permalink to &quot;Feature Flags&quot;">​</a></h1><p>neuron 把完整的特性集暴露为 Cargo 特性，宿主二进制只需为实际用到的部分付出编译时间和二进制体积。多数能力面都有可选特性；<code>candle</code> 默认启用，因为它覆盖最常见的情况（LLM + ASR + Rerank + Embedding + Vision 全部跑在 candle 后端上）。</p><h2 id="快速参考" tabindex="-1">快速参考 <a class="header-anchor" href="#快速参考" aria-label="Permalink to &quot;快速参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>拉取依赖</th><th>是否默认</th><th>启用内容</th></tr></thead><tbody><tr><td><code>candle</code></td><td><code>candle-core</code>、<code>candle-nn</code>、<code>candle-transformers</code>、<code>tokenizers</code>、<code>image</code>、<code>base64</code>、<code>safetensors</code></td><td>✅（默认）</td><td>LLM（Qwen/Llama/Phi/Mistral/ChatGLM）、ASR（Whisper）、Rerank（BGE/mxbai/jina）、Embedding（MiniLM）、Vision（YOLOv8/RT-DETR/DETR）</td></tr><tr><td><code>flash-attn</code></td><td><code>candle-flash-attn</code> + <code>candle-transformers/flash-attn</code></td><td>—</td><td>面向 Llama 2/3 + Mistral + Qwen 2/2.5/3/3.5 的 FlashAttention（仅 CUDA）</td></tr><tr><td><code>metal</code></td><td><code>candle-core/metal</code> + <code>candle-nn/metal</code> + <code>candle-transformers/metal</code></td><td>—</td><td>Apple Metal GPU 加速（M1/M2/M3）</td></tr><tr><td><code>cuda</code></td><td><code>candle-core/cuda</code> + <code>candle-nn/cuda</code> + <code>candle-transformers/cuda</code></td><td>—</td><td>NVIDIA CUDA GPU 加速</td></tr><tr><td><code>chronos2</code></td><td>（复用 candle）</td><td>—</td><td>时间序列预测（Sprint 3 进行中；candle 运行时开发中）</td></tr><tr><td><code>voxcpm</code></td><td><code>burn</code>、<code>burn-store</code>、<code>hound</code></td><td>—</td><td>经 VoxCpm 的 TTS（burn 0.21）</td></tr><tr><td><code>litert</code></td><td><code>litert-lm</code></td><td>—</td><td>经 Google LiteRT-LM 子进程的端上 LLM（Gemma 3）</td></tr><tr><td><code>asr-audio</code></td><td><code>symphonia</code>、<code>rubato</code></td><td>—</td><td>MP3 / FLAC / OGG-Vorbis ASR 解码（否则仅 WAV）</td></tr><tr><td><code>mistralrs</code></td><td><code>mistralrs</code> + （复用 candle）</td><td>—</td><td>经 mistral.rs 引擎的 LLM（40+ 模型家族）</td></tr><tr><td><code>tract</code></td><td><code>tract-onnx</code>、<code>ndarray</code>、<code>tokenizers</code>、<code>rustfft</code></td><td>—</td><td>纯 Rust ONNX 推理（Laya <code>POST /v1/decisions</code> + 经 <code>model.prepped.onnx</code> 的自有 ONNX SenseVoiceSmall ASR）</td></tr><tr><td><code>sherpa</code></td><td><code>sherpa-onnx</code></td><td>—</td><td><code>sherpa-onnx</code> 官方 Rust 绑定（1.13.x）。构建时从 GitHub releases 下载预构建静态库——宿主无需 cmake / C++ 工具链。支撑 SenseVoiceSmall 上的 sherpa-onnx ASR 运行时。</td></tr></tbody></table><h2 id="构建配方" tabindex="-1">构建配方 <a class="header-anchor" href="#构建配方" aria-label="Permalink to &quot;构建配方&quot;">​</a></h2><h3 id="最小开发构建" tabindex="-1">最小开发构建 <a class="header-anchor" href="#最小开发构建" aria-label="Permalink to &quot;最小开发构建&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-default-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle</span></span></code></pre></div><p>无 TTS、无 mistralrs、无 litert_lm、无 chronos2。只有 candle 用于 LLM/ASR/Rerank/Embedding/Vision。冷构建约 3-4 分钟。</p><h3 id="生产桌面-tauri-2-flutter-宿主" tabindex="-1">生产桌面（Tauri 2 / Flutter 宿主） <a class="header-anchor" href="#生产桌面-tauri-2-flutter-宿主" aria-label="Permalink to &quot;生产桌面（Tauri 2 / Flutter 宿主）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,voxcpm,asr-audio</span></span></code></pre></div><p>增加 VoxCpm TTS 与 MP3/FLAC/OGG-Vorbis ASR 支持。冷构建约 5-6 分钟。</p><h3 id="服务端推理-高吞吐" tabindex="-1">服务端推理（高吞吐） <a class="header-anchor" href="#服务端推理-高吞吐" aria-label="Permalink to &quot;服务端推理（高吞吐）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,mistralrs,asr-audio</span></span></code></pre></div><p>增加 mistralrs（40+ 家族、PagedAttention、KV cache）。冷构建约 8-10 分钟。</p><h3 id="全量构建-kitchen-sink" tabindex="-1">全量构建（kitchen sink） <a class="header-anchor" href="#全量构建-kitchen-sink" aria-label="Permalink to &quot;全量构建（kitchen sink）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,voxcpm,litert,mistralrs,asr-audio,flash-attn,cuda,chronos2</span></span></code></pre></div><p>全部特性。冷构建约 12-15 分钟。</p><h3 id="边缘-移动端-无-gpu-最小二进制" tabindex="-1">边缘 / 移动端（无 GPU，最小二进制） <a class="header-anchor" href="#边缘-移动端-无-gpu-最小二进制" aria-label="Permalink to &quot;边缘 / 移动端（无 GPU，最小二进制）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-default-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optionally: --features candle,litert for on-device LLM</span></span></code></pre></div><h2 id="哪些内容不受特性开关控制" tabindex="-1">哪些内容不受特性开关控制 <a class="header-anchor" href="#哪些内容不受特性开关控制" aria-label="Permalink to &quot;哪些内容不受特性开关控制&quot;">​</a></h2><p>HTTP 面（axum）、OpenAI / Anthropic 线上格式、多源模型注册表、<code>ApiAdapter</code> 分发系统、运行时注册表模式，以及全部 6 个能力面的 trait 形态<strong>总是编译在内</strong>。只有引擎后端受特性开关控制。</p><p>这是有意为之：你可以在运行时切换引擎（例如把 LLM 从 candle 换成 mistralrs）而无需重新编译。特性开关只控制哪些引擎作为可选项存在。</p><h2 id="运行时选择-vs-构建期选择" tabindex="-1">运行时选择 vs 构建期选择 <a class="header-anchor" href="#运行时选择-vs-构建期选择" aria-label="Permalink to &quot;运行时选择 vs 构建期选择&quot;">​</a></h2><p>用某些特性构建完成后，运行时选择会为给定请求挑出具体引擎：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Built with: candle,voxcpm,mistralrs</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Runtime:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">candle</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # uses candle (available)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mistralrs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # uses mistralrs (available)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">litert</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # ERROR — litert not built</span></span></code></pre></div><p>如果你试图使用未编译进去的运行时，启动时会得到清晰的错误：<code>Error: requested runtime &#39;litert&#39; not in this build (built with: candle,voxcpm)</code>。</p><h2 id="ci-建议" tabindex="-1">CI 建议 <a class="header-anchor" href="#ci-建议" aria-label="Permalink to &quot;CI 建议&quot;">​</a></h2><ul><li><strong>默认构建</strong>（仅 <code>--features candle</code>）：捕捉 90% 的回归。速度快。</li><li><strong>全量构建</strong>（所有特性）：捕捉特性开关之间的相互作用与特定缺陷。每个 PR 跑一次，不必每个 commit 都跑。</li></ul><p>CI 矩阵示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">matrix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  features</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # minimal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,voxcpm&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # + TTS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,mistralrs&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # + multi-family</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,voxcpm,litert,mistralrs,asr-audio&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # full</span></span></code></pre></div><h2 id="测试特性开关的相互作用" tabindex="-1">测试特性开关的相互作用 <a class="header-anchor" href="#测试特性开关的相互作用" aria-label="Permalink to &quot;测试特性开关的相互作用&quot;">​</a></h2><p>有些特性相互依赖或有特定的顺序要求。常见的坑：</p><ul><li><code>flash-attn</code> <strong>需要 CUDA</strong> 才有用（macOS 上能构建成功，但 <code>flash_attn</code> 调用会在运行时失败）。务必与 <code>cuda</code> 组合。</li><li><code>mistralrs</code> <strong>隐式激活 candle</strong>，因为 mistral.rs 内部基于 candle-core 0.10.2 构建。</li><li><code>voxcpm</code> <strong>引入 burn</strong>，这是一棵全新的依赖树（约 3-5 分钟编译时间）。不需要 TTS 就不要加。</li><li><code>litert</code> <strong>引入 <code>litert-lm</code></strong>，但运行时你还需要 <code>PATH</code> 上有 <code>lit</code> 二进制（该 Rust crate 只是子进程包装器，不是自包含引擎）。</li></ul><h2 id="编译时间表" tabindex="-1">编译时间表 <a class="header-anchor" href="#编译时间表" aria-label="Permalink to &quot;编译时间表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性组合</th><th>冷构建</th><th>增量</th></tr></thead><tbody><tr><td><code>--features candle</code></td><td>3-4 分钟</td><td>30-60 秒</td></tr><tr><td><code>--features candle,voxcpm</code></td><td>5-6 分钟</td><td>1-2 分钟</td></tr><tr><td><code>--features candle,mistralrs</code></td><td>8-10 分钟</td><td>1-3 分钟</td></tr><tr><td><code>--features candle,voxcpm,litert,mistralrs,asr-audio</code></td><td>10-12 分钟</td><td>2-3 分钟</td></tr><tr><td>全量（+ <code>flash-attn,cuda,chronos2</code>）</td><td>12-15 分钟</td><td>2-4 分钟</td></tr></tbody></table><p>这些数字是近似值，且强烈依赖宿主机（CPU、内存、SSD）。在启用 <code>sccache</code> 的快机上，冷构建可缩短 30-50%。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/neuron/zh/concepts/engines">引擎选择</a> — 何时使用哪个引擎</li><li><a href="/neuron/zh/guide/quick-start">快速开始</a> — 最小嵌入示例</li><li><a href="/neuron/zh/concepts/architecture">架构</a> — 数据流如何把注册表接到处理器</li></ul>`,38)])])}const u=t(d,[["render",l]]);export{k as __pageData,u as default};
